//! The default lighting of prefab mode: a small studio HDRI that lights the
//! prefab through image-based lighting. It belongs to the scene view, not to
//! the prefab, so nothing of it is saved or shown in the hierarchy.
//!
//! The HDRI, `assets/skyboxes/prefab_studio.hdr`, is generated by the
//! `generator` module below.
//! To regenerate it, and write a tone-mapped PNG preview, run
//!
//! ```text
//! CALYX_WRITE_PREFAB_ENVIRONMENT=1 cargo test -p editor prefab_mode::environment
//! ```
//!
//! with `CALYX_PREFAB_ENVIRONMENT_PREVIEW=<file.png>` set for the preview.

use engine::assets::skybox::Skybox;
use engine::core::Ref;
use engine::render::SceneEnvironment;

/// The built-in studio HDRI that lights prefab mode, as an asset name; the
/// `generator` module below generates it. It lights the prefab without being
/// drawn, so [`PREFAB_MODE_BACKDROP`](super::PREFAB_MODE_BACKDROP) stays the
/// background.
pub(super) const PREFAB_ENVIRONMENT_ASSET: &str = "skyboxes/prefab_studio";
/// How strongly the studio HDRI lights the prefab, as a sky light's intensity:
/// bright enough that a prefab reads about as it does in the sandbox scene once
/// the view is tone mapped with ACES at 0 EV.
const PREFAB_ENVIRONMENT_INTENSITY: f32 = 6.0;

/// The scene view's lighting in prefab mode, lighting with `skybox`, the
/// loaded studio HDRI, without drawing it, so the prefab backdrop shows.
/// `None` outside prefab mode, so the scene's own lights apply.
pub(super) fn scene_view_environment(
    prefab_mode: bool,
    skybox: Option<&Ref<Skybox>>,
) -> Option<SceneEnvironment> {
    let skybox = skybox.filter(|_| prefab_mode)?;
    Some(SceneEnvironment {
        skybox: skybox.clone(),
        intensity: PREFAB_ENVIRONMENT_INTENSITY,
        draw_sky: false,
    })
}

/// The generator of the studio HDRI, which only its test runs.
#[cfg(test)]
mod generator {
    use image::Rgb;
    use nalgebra_glm::Vec3;

    /// The HDRI's file inside the built-in asset root, `assets/`.
    pub(super) const PREFAB_ENVIRONMENT_FILE: &str = "skyboxes/prefab_studio.hdr";
    /// Width of the generated HDRI; its height is half of it.
    const HDRI_WIDTH: usize = 256;
    /// Radiance straight up: a bright, slightly cool sky.
    const ZENITH: [f32; 3] = [1.15, 1.2, 1.3];
    /// Radiance at the horizon: neutral mid-gray.
    const HORIZON: [f32; 3] = [0.5, 0.5, 0.5];
    /// Radiance straight down: a dark, slightly warm floor.
    const NADIR: [f32; 3] = [0.1, 0.095, 0.09];
    /// Elevation of the key, the HDRI's bright spot that gives the prefab a
    /// shading direction.
    const KEY_ELEVATION_DEG: f32 = 45.0;
    /// Azimuth of the key, from +X towards +Z.
    const KEY_AZIMUTH_DEG: f32 = 45.0;
    /// Peak radiance of the key's soft blob, on top of the sky.
    const KEY_PEAK: [f32; 3] = [30.0, 28.5, 25.5];
    /// Angular falloff of the key blob, as `1 - cos` of the angle at which it
    /// drops to `1/e`: about 11 degrees.
    const KEY_SPREAD: f32 = 0.02;

    /// The direction towards the key, from the prefab: up and to the side at
    /// [`KEY_ELEVATION_DEG`] and [`KEY_AZIMUTH_DEG`].
    pub(super) fn key_direction() -> Vec3 {
        direction(KEY_ELEVATION_DEG.to_radians(), KEY_AZIMUTH_DEG.to_radians())
    }

    /// The world direction at `elevation` above the horizon and `azimuth`
    /// around it, as the engine's environment shaders map an equirectangular
    /// image: azimuth runs from the +X axis towards +Z.
    fn direction(elevation: f32, azimuth: f32) -> Vec3 {
        Vec3::new(
            elevation.cos() * azimuth.cos(),
            elevation.sin(),
            elevation.cos() * azimuth.sin(),
        )
    }

    /// The studio environment's radiance towards `direction`.
    pub(super) fn studio_radiance(direction: Vec3) -> [f32; 3] {
        let up = direction.y.clamp(-1.0, 1.0);
        let (to, t) = if up >= 0.0 {
            (ZENITH, smoothstep(up.sqrt()))
        } else {
            (NADIR, smoothstep((-up).sqrt()))
        };
        let key = ((direction.dot(&key_direction()) - 1.0) / KEY_SPREAD).exp();
        std::array::from_fn(|channel| {
            HORIZON[channel] + (to[channel] - HORIZON[channel]) * t + KEY_PEAK[channel] * key
        })
    }

    fn smoothstep(t: f32) -> f32 {
        let t = t.clamp(0.0, 1.0);
        t * t * (3.0 - 2.0 * t)
    }

    /// The studio HDRI as an equirectangular image, row by row from the top,
    /// `HDRI_WIDTH` by half of it.
    pub(super) fn studio_hdri() -> (Vec<Rgb<f32>>, usize, usize) {
        let (width, height) = (HDRI_WIDTH, HDRI_WIDTH / 2);
        let pixels = (0..height)
            .flat_map(|y| (0..width).map(move |x| (x, y)))
            .map(|(x, y)| {
                let elevation = (0.5 - (y as f32 + 0.5) / height as f32) * std::f32::consts::PI;
                let azimuth = ((x as f32 + 0.5) / width as f32 - 0.5) * std::f32::consts::TAU;
                Rgb(studio_radiance(direction(elevation, azimuth)))
            })
            .collect();
        (pixels, width, height)
    }
}

#[cfg(test)]
mod tests {
    use super::generator::{key_direction, studio_hdri, studio_radiance, PREFAB_ENVIRONMENT_FILE};
    use super::{scene_view_environment, PREFAB_ENVIRONMENT_INTENSITY};
    use engine::assets::skybox::Skybox;
    use engine::test_support::TestAssets;
    use image::codecs::hdr::HdrEncoder;
    use nalgebra_glm::Vec3;
    use std::path::PathBuf;

    fn committed_file() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("..")
            .join("assets")
            .join(PREFAB_ENVIRONMENT_FILE)
    }

    /// Writes the HDRI, and its preview, when asked to through the
    /// environment, so regenerating it is one test run.
    fn write_when_asked() {
        if std::env::var_os("CALYX_WRITE_PREFAB_ENVIRONMENT").is_none() {
            return;
        }
        let (pixels, width, height) = studio_hdri();
        let file = std::fs::File::create(committed_file()).expect("HDRI file should open");
        HdrEncoder::new(std::io::BufWriter::new(file))
            .encode(&pixels, width, height)
            .expect("HDRI should encode");
        if let Some(preview) = std::env::var_os("CALYX_PREFAB_ENVIRONMENT_PREVIEW") {
            // Reinhard tone mapping and sRGB-like gamma, for looking at it.
            let bytes = pixels
                .iter()
                .flat_map(|pixel| pixel.0)
                .map(|value| ((value / (value + 1.0)).powf(1.0 / 2.2) * 255.0).round() as u8)
                .collect::<Vec<_>>();
            image::RgbImage::from_raw(width as u32, height as u32, bytes)
                .expect("preview should fit")
                .save(preview)
                .expect("preview should save");
        }
    }

    #[test]
    fn the_committed_hdri_matches_its_generator() {
        write_when_asked();
        let committed = image::open(committed_file())
            .expect("the prefab HDRI should decode")
            .to_rgb32f();
        let (pixels, width, height) = studio_hdri();
        assert_eq!(
            (committed.width() as usize, committed.height() as usize),
            (width, height)
        );
        for (index, (committed, generated)) in committed.pixels().zip(&pixels).enumerate() {
            for channel in 0..3 {
                let (a, b) = (committed.0[channel], generated.0[channel]);
                // RGBE keeps about 8 bits of mantissa per pixel.
                assert!(
                    (a - b).abs() <= 0.01 + 0.02 * b.abs(),
                    "pixel {index} channel {channel}: committed {a}, generated {b}; \
                     regenerate it as the module docs say"
                );
            }
        }
    }

    #[test]
    fn the_studio_is_bright_above_dark_below_with_a_key_up_high() {
        let up = studio_radiance(Vec3::y());
        let horizon = studio_radiance(Vec3::x());
        let down = studio_radiance(-Vec3::y());
        let key = studio_radiance(key_direction());
        assert!(up[1] > horizon[1] && horizon[1] > down[1]);
        assert!(key[0] > 5.0, "the key blob is well above the sky: {key:?}");
        assert!((key_direction().y - 45f32.to_radians().sin()).abs() < 1e-5);
    }

    #[test]
    fn only_prefab_mode_lights_the_view_with_the_studio() {
        let assets = TestAssets::engine();
        let registries = assets.registries();
        let skybox = registries
            .assets
            .read()
            .load::<Skybox>("skyboxes/prefab_studio")
            .expect("the prefab HDRI is a built-in asset");

        let environment = scene_view_environment(true, Some(&skybox))
            .expect("prefab mode supplies the environment");
        assert_eq!(environment.skybox.id(), skybox.id());
        assert_eq!(environment.intensity, PREFAB_ENVIRONMENT_INTENSITY);
        assert!(!environment.draw_sky, "the backdrop stays visible");

        assert!(
            scene_view_environment(false, Some(&skybox)).is_none(),
            "outside prefab mode the scene's own lighting applies"
        );
        assert!(scene_view_environment(true, None).is_none());
    }
}
